```go
package walstore

import (
	"encoding/binary"
	"errors"
	"hash/crc32"
)

// CRC32C (Castagnoli) is used, as required.
var crcTable = crc32.MakeTable(crc32.Castagnoli)

const (
	frameMagic     = uint32(0x57414c31) // "WAL1"
	frameHeaderLen = 12                 // magic(4) + length(4) + crc(4)
)

// ErrTornTail indicates the WAL ended in an incomplete or corrupt frame.
var ErrTornTail = errors.New("walstore: torn or corrupt WAL frame")

// Record is a single key/value mutation inside a batch.
type Record struct {
	Key string
	Val string
}

// Batch is an atomically applied group of records carrying a monotonic seq.
type Batch struct {
	Seq     uint64
	Records []Record
}

// encodeBatch serialises a batch into a single WAL frame payload.
func encodeBatch(b Batch) []byte {
	// seq(8) + count(4) + sum(4 + len(k) + 4 + len(v))
	n := 12
	for _, r := range b.Records {
		n += 8 + len(r.Key) + len(r.Val)
	}
	buf := make([]byte, n)
	binary.LittleEndian.PutUint64(buf[0:8], b.Seq)
	binary.LittleEndian.PutUint32(buf[8:12], uint32(len(b.Records)))
	off := 12
	for _, r := range b.Records {
		binary.LittleEndian.PutUint32(buf[off:off+4], uint32(len(r.Key)))
		off += 4
		copy(buf[off:], r.Key)
		off += len(r.Key)
		binary.LittleEndian.PutUint32(buf[off:off+4], uint32(len(r.Val)))
		off += 4
		copy(buf[off:], r.Val)
		off += len(r.Val)
	}
	return buf
}

// decodeBatch parses a frame payload into a Batch.
func decodeBatch(p []byte) (Batch, error) {
	if len(p) < 12 {
		return Batch{}, ErrTornTail
	}
	var b Batch
	b.Seq = binary.LittleEndian.Uint64(p[0:8])
	count := binary.LittleEndian.Uint32(p[8:12])
	if count > uint32(len(p))/8+1 { // cheap sanity guard against absurd counts
		return Batch{}, ErrTornTail
	}
	off := 12
	for i := uint32(0); i < count; i++ {
		if off+4 > len(p) {
			return Batch{}, ErrTornTail
		}
		kl := binary.LittleEndian.Uint32(p[off : off+4])
		off += 4
		if off+int(kl) > len(p) {
			return Batch{}, ErrTornTail
		}
		k := string(p[off : off+int(kl)])
		off += int(kl)
		if off+4 > len(p) {
			return Batch{}, ErrTornTail
		}
		vl := binary.LittleEndian.Uint32(p[off : off+4])
		off += 4
		if off+int(vl) > len(p) {
			return Batch{}, ErrTornTail
		}
		v := string(p[off : off+int(vl)])
		off += int(vl)
		b.Records = append(b.Records, Record{Key: k, Val: v})
	}
	if off != len(p) {
		return Batch{}, ErrTornTail
	}
	return b, nil
}

// appendFrame writes a length-prefixed, CRC32C-protected frame.
func appendFrame(dst []byte, payload []byte) []byte {
	var hdr [frameHeaderLen]byte
	binary.LittleEndian.PutUint32(hdr[0:4], frameMagic)
	binary.LittleEndian.PutUint32(hdr[4:8], uint32(len(payload)))
	binary.LittleEndian.PutUint32(hdr[8:12], crc32.Checksum(payload, crcTable))
	dst = append(dst, hdr[:]...)
	dst = append(dst, payload...)
	return dst
}

// scanFrames returns every fully-valid batch encoded in data, in order, and the
// number of leading bytes consumed. The scan stops at the first frame that is
// incomplete or fails its CRC. The trailing region is the torn tail and is
// discarded on recovery.
func scanFrames(data []byte) (batches []Batch, ends []int, consumed int, torn bool) {
	off := 0
	for {
		if off == len(data) {
			return batches, ends, off, false
		}
		if off+frameHeaderLen > len(data) {
			return batches, ends, off, true
		}
		magic := binary.LittleEndian.Uint32(data[off : off+4])
		if magic != frameMagic {
			return batches, ends, off, true
		}
		l := binary.LittleEndian.Uint32(data[off+4 : off+8])
		want := binary.LittleEndian.Uint32(data[off+8 : off+12])
		start := off + frameHeaderLen
		end := start + int(l)
		if l > uint32(len(data)) || end > len(data) {
			return batches, ends, off, true
		}
		payload := data[start:end]
		if crc32.Checksum(payload, crcTable) != want {
			return batches, ends, off, true
		}
		b, err := decodeBatch(payload)
		if err != nil {
			return batches, ends, off, true
		}
		batches = append(batches, b)
		ends = append(ends, end)
		off = end
	}
}
