### `manifest.go`

```go
package walstore

import (
	"encoding/binary"
	"errors"
	"hash/crc32"
	"os"
	"path/filepath"
)

// Manifest is the durable fence record. Epoch is bumped by every writer
// acquisition; any writer holding a lower epoch is stale and must stop.
type Manifest struct {
	Epoch   uint64
	BaseGen uint64
	BaseSeq uint64
}

const manifestMagic = uint32(0x4d414e31) // "MAN1"

func manifestPath(dir string) string { return filepath.Join(dir, "MANIFEST") }

func encodeManifest(m Manifest) []byte {
	var buf [32]byte
	binary.LittleEndian.PutUint32(buf[0:4], manifestMagic)
	binary.LittleEndian.PutUint64(buf[4:12], m.Epoch)
	binary.LittleEndian.PutUint64(buf[12:20], m.BaseGen)
	binary.LittleEndian.PutUint64(buf[20:28], m.BaseSeq)
	binary.LittleEndian.PutUint32(buf[28:32], crc32.Checksum(buf[0:28], crcTable))
	out := make([]byte, 32)
	copy(out, buf[:])
	return out
}

func decodeManifest(data []byte) (Manifest, error) {
	if len(data) != 32 {
		return Manifest{}, errors.New("walstore: bad manifest length")
	}
	if binary.LittleEndian.Uint32(data[0:4]) != manifestMagic {
		return Manifest{}, errors.New("walstore: bad manifest magic")
	}
	if crc32.Checksum(data[0:28], crcTable) != binary.LittleEndian.Uint32(data[28:32]) {
		return Manifest{}, errors.New("walstore: manifest checksum mismatch")
	}
	return Manifest{
		Epoch:   binary.LittleEndian.Uint64(data[4:12]),
		BaseGen: binary.LittleEndian.Uint64(data[12:20]),
		BaseSeq: binary.LittleEndian.Uint64(data[20:28]),
	}, nil
}

func readManifest(dir string) (Manifest, error) {
	raw, err := os.ReadFile(manifestPath(dir))
	if err != nil {
		return Manifest{}, err
	}
	return decodeManifest(raw)
}

// writeManifestFsync atomically replaces the manifest and fsyncs both the file
// and its parent directory so the epoch bump is durable before use.
func writeManifestFsync(dir string, m Manifest) error {
	tmp := manifestPath(dir) + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	if _, err := f.Write(encodeManifest(m)); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := os.Rename(tmp, manifestPath(dir)); err != nil {
		return err
	}
	return fsyncDir(dir)
}

func fsyncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer d.Close()
	return d.Sync()
}
