### `sst.go`

```go
package walstore

import (
	"encoding/binary"
	"errors"
	"fmt"
	"hash/crc32"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

const sstMagic = uint32(0x53535431) // "SST1"

// SSTable is an immutable, checksummed sorted snapshot at a generation.
type SSTable struct {
	Gen uint64
	Seq uint64 // highest sequence number included
	KV  map[string]string
}

// encodeSST serialises the table plus a footer protected by CRC32C.
func encodeSST(t SSTable) []byte {
	keys := make([]string, 0, len(t.KV))
	for k := range t.KV {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	buf := make([]byte, 0, 16+len(keys)*16)
	var tmp [8]byte
	binary.LittleEndian.PutUint64(tmp[:], t.Seq)
	buf = append(buf, tmp[:]...)
	binary.LittleEndian.PutUint32(tmp[:4], uint32(len(keys)))
	buf = append(buf, tmp[:4]...)
	for _, k := range keys {
		v := t.KV[k]
		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(k)))
		buf = append(buf, tmp[:4]...)
		buf = append(buf, k...)
		binary.LittleEndian.PutUint32(tmp[:4], uint32(len(v)))
		buf = append(buf, tmp[:4]...)
		buf = append(buf, v...)
	}
	// footer: crc(4) over all preceding bytes, then magic(4)
	var crcBuf [4]byte
	binary.LittleEndian.PutUint32(crcBuf[:], crc32.Checksum(buf, crcTable))
	buf = append(buf, crcBuf[:]...)
	binary.LittleEndian.PutUint32(crcBuf[:], sstMagic)
	buf = append(buf, crcBuf[:]...)
	return buf
}

// decodeSST validates and parses an SSTable. A truncated or corrupt table
// (e.g. an fsync that never completed) returns an error.
func decodeSST(data []byte) (SSTable, error) {
	if len(data) < 16 {
		return SSTable{}, errors.New("walstore: short SSTable")
	}
	body := data[:len(data)-8]
	footer := data[len(data)-8:]
	if binary.LittleEndian.Uint32(footer[4:8]) != sstMagic {
		return SSTable{}, errors.New("walstore: bad SSTable magic")
	}
	if crc32.Checksum(body, crcTable) != binary.LittleEndian.Uint32(footer[0:4]) {
		return SSTable{}, errors.New("walstore: SSTable checksum mismatch")
	}
	var t SSTable
	t.Seq = binary.LittleEndian.Uint64(body[0:8])
	count := binary.LittleEndian.Uint32(body[8:12])
	off := 12
	t.KV = make(map[string]string, count)
	for i := uint32(0); i < count; i++ {
		if off+4 > len(body) {
			return SSTable{}, errors.New("walstore: truncated SSTable body")
		}
		kl := binary.LittleEndian.Uint32(body[off : off+4])
		off += 4
		if off+int(kl) > len(body) {
			return SSTable{}, errors.New("walstore: truncated key")
		}
		k := string(body[off : off+int(kl)])
		off += int(kl)
		if off+4 > len(body) {
			return SSTable{}, errors.New("walstore: truncated SSTable body")
		}
		vl := binary.LittleEndian.Uint32(body[off : off+4])
		off += 4
		if off+int(vl) > len(body) {
			return SSTable{}, errors.New("walstore: truncated value")
		}
		v := string(body[off : off+int(vl)])
		off += int(vl)
		t.KV[k] = v
	}
	if off != len(body) {
		return SSTable{}, errors.New("walstore: trailing SSTable bytes")
	}
	return t, nil
}

// maxSSTGen returns the highest generation number present on disk, valid or
// not, so fresh writes never reuse a generation slot.
func maxSSTGen(dir string) uint64 {
	entries, err := os.ReadDir(filepath.Join(dir, "sst"))
	if err != nil {
		return 0
	}
	var max uint64
	for _, e := range entries {
		name := e.Name()
		if !strings.HasSuffix(name, ".sst") {
			continue
		}
		gen, err := strconv.ParseUint(strings.TrimSuffix(name, ".sst"), 10, 64)
		if err != nil {
			continue
		}
		if gen > max {
			max = gen
		}
	}
	return max
}

// sstPath returns the canonical path of a generation's SSTable.
func sstPath(dir string, gen uint64) string {
	return filepath.Join(dir, "sst", fmt.Sprintf("%020d.sst", gen))
}

// scanSSTGenerations validates every generation present on disk and returns the
// newest one whose contents are durable and checksum-clean. The manifest's
// pointer is only a hint; this is the authoritative durability check.
func scanSSTGenerations(dir string) (SSTable, bool, error) {
	entries, err := os.ReadDir(filepath.Join(dir, "sst"))
	if err != nil {
		if os.IsNotExist(err) {
			return SSTable{}, false, nil
		}
		return SSTable{}, false, err
	}
	var gens []uint64
	for _, e := range entries {
		name := e.Name()
		if !strings.HasSuffix(name, ".sst") {
			continue
		}
		gen, err := strconv.ParseUint(strings.TrimSuffix(name, ".sst"), 10, 64)
		if err != nil {
			continue
		}
		gens = append(gens, gen)
	}
	sort.Slice(gens, func(i, j int) bool { return gens[i] > gens[j] })
	for _, gen := range gens {
		raw, err := os.ReadFile(sstPath(dir, gen))
		if err != nil {
			continue
		}
		t, err := decodeSST(raw)
		if err != nil {
			continue // incomplete fsync / torn generation: skip
		}
		t.Gen = gen
		return t, true, nil
	}
	return SSTable{}, false, nil
}
