### `store.go`

```go
package walstore

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

// StaleEpochError is returned when a writer tries to mutate the store while a
// newer writer has fenced it by advancing the manifest epoch.
type StaleEpochError struct {
	Held   uint64
	OnDisk uint64
}

func (e *StaleEpochError) Error() string {
	return fmt.Sprintf("walstore: stale manifest epoch: writer holds %d, on-disk is %d", e.Held, e.OnDisk)
}

// Store is the single-writer handle over one directory.
type Store struct {
	mu       sync.Mutex
	dir      string
	epoch    uint64
	seq      uint64
	nextGen  uint64
	mem      map[string]string
	wal      *os.File
	done     bool
}

// Recovered is the result of replaying a WAL image.
type Recovered struct {
	Mem      map[string]string
	Seq      uint64
	Applied  []Batch
	Consumed int
	Torn     bool
}

// recoverState replays WAL frames on top of a base snapshot. Only batches with
// contiguous, strictly-increasing sequence numbers are applied; the first
// incomplete, corrupt, or out-of-order frame terminates replay (torn tail).
func recoverState(raw []byte, base map[string]string, baseSeq uint64) (Recovered, error) {
	mem := make(map[string]string, len(base))
	for k, v := range base {
		mem[k] = v
	}
	batches, ends, consumed, torn := scanFrames(raw)
	res := Recovered{Mem: mem, Seq: baseSeq, Consumed: consumed, Torn: torn}
	prev := baseSeq
	applied := 0
	for _, b := range batches {
		if b.Seq != prev+1 {
			// Stop before the out-of-order frame; only the validated
			// prefix may be physically retained.
			res.Torn = true
			if applied == 0 {
				res.Consumed = 0
			} else {
				res.Consumed = ends[applied-1]
			}
			return res, nil
		}
		for _, r := range b.Records {
			mem[r.Key] = r.Val
		}
		prev = b.Seq
		res.Seq = b.Seq
		res.Applied = append(res.Applied, b)
		applied++
	}
	return res, nil
}

// Open recovers the store and acquires a fresh writer epoch. Any previously
// open writer becomes stale.
func Open(dir string) (*Store, error) {
	if err := os.MkdirAll(filepath.Join(dir, "sst"), 0o755); err != nil {
		return nil, err
	}
	if err := os.MkdirAll(filepath.Join(dir, "wal"), 0o755); err != nil {
		return nil, err
	}

	m, err := readManifest(dir)
	if err != nil {
		if !os.IsNotExist(err) {
			return nil, err
		}
		m = Manifest{}
	}

	sst, ok, err := scanSSTGenerations(dir)
	if err != nil {
		return nil, err
	}
	var base map[string]string
	var baseSeq uint64
	var baseGen uint64
	if ok {
		base = sst.KV
		baseSeq = sst.Seq
		baseGen = sst.Gen
	} else {
		base = map[string]string{}
	}

	walFile := filepath.Join(dir, "wal", "000001.wal")
	raw, err := os.ReadFile(walFile)
	if err != nil && !os.IsNotExist(err) {
		return nil, err
	}
	rec, err := recoverState(raw, base, baseSeq)
	if err != nil {
		return nil, err
	}

	// Physically drop the torn tail so subsequent appends are clean.
	f, err := os.OpenFile(walFile, os.O_CREATE|os.O_RDWR, 0o644)
	if err != nil {
		return nil, err
	}
	if err := f.Truncate(int64(rec.Consumed)); err != nil {
		f.Close()
		return nil, err
	}
	if _, err := f.Seek(0, os.SEEK_END); err != nil {
		f.Close()
		return nil, err
	}

	s := &Store{
		dir:     dir,
		epoch:   m.Epoch + 1,
		seq:     rec.Seq,
		nextGen: maxSSTGen(dir) + 1,
		mem:     rec.Mem,
		wal:     f,
	}
	// Persist the epoch fence before returning the writer.
	if err := writeManifestFsync(dir, Manifest{Epoch: s.epoch, BaseGen: baseGen, BaseSeq: rec.Seq}); err != nil {
		f.Close()
		return nil, err
	}
	return s, nil
}

// Epoch returns the writer epoch held by this handle.
func (s *Store) Epoch() uint64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.epoch
}

// Seq returns the highest applied sequence number.
func (s *Store) Seq() uint64 {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.seq
}

// Get returns the current value for a key.
func (s *Store) Get(key string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	v, ok := s.mem[key]
	return v, ok
}

// checkEpochLocked fails if another writer advanced the manifest epoch.
func (s *Store) checkEpochLocked() error {
	m, err := readManifest(s.dir)
	if err != nil {
		return err
	}
	if m.Epoch != s.epoch {
		return &StaleEpochError{Held: s.epoch, OnDisk: m.Epoch}
	}
	return nil
}

// Append atomically applies one batch, fsyncing its single WAL frame first.
func (s *Store) Append(records []Record) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.done {
		return errors.New("walstore: store is closed")
	}
	if err := s.checkEpochLocked(); err != nil {
		return err
	}
	batch := Batch{Seq: s.seq + 1, Records: records}
	frame := appendFrame(nil, encodeBatch(batch))
	if _, err := s.wal.Write(frame); err != nil {
		return err
	}
	if err := s.wal.Sync(); err != nil {
		return err
	}
	for _, r := range records {
		s.mem[r.Key] = r.Val
	}
	s.seq = batch.Seq
	return nil
}

// Flush writes the current in-memory state as a new checksummed SSTable
// generation, fsyncs it, then publishes it in the manifest. The manifest
// pointer is only a hint; recovery re-validates every generation.
func (s *Store) Flush() (uint64, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.done {
		return 0, errors.New("walstore: store is closed")
	}
	if err := s.checkEpochLocked(); err != nil {
		return 0, err
	}
	gen := s.nextGen
	table := SSTable{Gen: gen, Seq: s.seq, KV: s.mem}
	raw := encodeSST(table)

	tmp := sstPath(s.dir, gen) + ".tmp"
	f, err := os.OpenFile(tmp, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o644)
	if err != nil {
		return 0, err
	}
	if _, err := f.Write(raw); err != nil {
		f.Close()
		return 0, err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return 0, err
	}
	if err := f.Close(); err != nil {
		return 0, err
	}
	if err := os.Rename(tmp, sstPath(s.dir, gen)); err != nil {
		return 0, err
	}
	if err := fsyncDir(filepath.Join(s.dir, "sst")); err != nil {
		return 0, err
	}
	if err := writeManifestFsync(s.dir, Manifest{Epoch: s.epoch, BaseGen: gen, BaseSeq: s.seq}); err != nil {
		return 0, err
	}
	s.nextGen = gen + 1
	// The WAL prefix covered by this SSTable is no longer needed.
	if err := s.wal.Truncate(0); err != nil {
		return 0, err
	}
	if _, err := s.wal.Seek(0, os.SEEK_END); err != nil {
		return 0, err
	}
	if err := s.wal.Sync(); err != nil {
		return 0, err
	}
	return gen, nil
}

// Close releases the writer handle.
func (s *Store) Close() error {
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.done {
		return nil
	}
	s.done = true
	return s.wal.Close()
}
