// frameLen returns the on-disk size of one encoded batch frame.
func frameLen(b Batch) int {
	return frameHeaderLen + len(encodeBatch(b))
}

// buildWAL encodes batches into a raw WAL image and returns per-frame end
// offsets.
func buildWAL(batches []Batch) ([]byte, []int) {
	var raw []byte
	ends := make([]int, len(batches))
	for i, b := range batches {
		raw = appendFrame(raw, encodeBatch(b))
		ends[i] = len(raw)
	}
	return raw, ends
}

func modelStates(batches []Batch) []map[string]string {
	states := make([]map[string]string, len(batches)+1)
	states[0] = map[string]string{}
	for i, b := range batches {
		m := make(map[string]string, len(states[i]))
		for k, v := range states[i] {
			m[k] = v
		}
		for _, r := range b.Records {
			m[r.Key] = r.Val
		}
		states[i+1] = m
	}
	return states
}

func randomBatches(rng *rand.Rand, n int) []Batch {
	batches := make([]Batch, n)
	for i := range batches {
		recs := make([]Record, 1+rng.Intn(4))
		for j := range recs {
			recs[j] = Record{
				Key: fmt.Sprintf("k%d_%d", i, rng.Intn(3)),
				Val: fmt.Sprintf("v%d_%d", i, rng.Intn(1000)),
			}
		}
		batches[i] = Batch{Seq: uint64(i + 1), Records: recs}
	}
	return batches
}

// TestTornTailPrefixProperty is the required property test: at least 200 random
// truncation offsets crossed with random batch boundaries. For every image the
// recovered state must equal some prefix of committed batches, never a partial
// batch and never a non-prefix.
func TestTornTailPrefixProperty(t *testing.T) {
	rng := rand.New(rand.NewSource(0xC0FFEE))
	const seeds = 8
	checks := 0

	for seed := 0; seed < seeds; seed++ {
		batches := randomBatches(rng, 1+rng.Intn(40))
		raw, ends := buildWAL(batches)
		states := modelStates(batches)

		// 200+ offsets per seed, plus every frame boundary.
		offsets := make([]int, 0, 260)
		for i := 0; i < 256; i++ {
			offsets = append(offsets, rng.Intn(len(raw)+1))
		}
		for _, e := range ends {
			offsets = append(offsets, e, e-1)
		}

		for _, off := range offsets {
			if off < 0 {
				continue
			}
			if off > len(raw) {
				continue
			}
			checks++
			rec, err := recoverState(raw[:off], map[string]string{}, 0)
			if err != nil {
				t.Fatalf("recover error: %v", err)
			}

			// Highest fully-contained frame index.
			wantApplied := 0
			for i, e := range ends {
				if e <= off {
					wantApplied = i + 1
				}
			}
			if len(rec.Applied) != wantApplied {
				t.Fatalf("seed=%d off=%d: applied=%d want=%d", seed, off, len(rec.Applied), wantApplied)
			}
			// Sequence numbers must be strictly monotonic & contiguous.
			for i, b := range rec.Applied {
				if b.Seq != uint64(i+1) {
					t.Fatalf("seed=%d off=%d: non-monotonic seq at %d: %d", seed, off, i, b.Seq)
				}
			}
			// State must equal the exact committed prefix.
			if !equalKV(rec.Mem, states[wantApplied]) {
				t.Fatalf("seed=%d off=%d: state mismatch\n got=%v\nwant=%v", seed, off, rec.Mem, states[wantApplied])
			}
			if rec.Seq != uint64(wantApplied) {
				t.Fatalf("seed=%d off=%d: seq=%d want=%d", seed, off, rec.Seq, wantApplied)
			}
		}
	}
	if checks < 200 {
		t.Fatalf("only %d checks, need >= 200", checks)
	}
	t.Logf("verified %d truncation offsets across %d random batch streams", checks, seeds)
}

// TestAtomicBatchDiscard proves a torn multi-key batch is fully discarded.
func TestAtomicBatchDiscard(t *testing.T) {
	recs := []Record{{Key: "a", Val: "1"}, {Key: "b", Val: "2"}, {Key: "c", Val: "3"}}
	b := Batch{Seq: 1, Records: recs}
	full := appendFrame(nil, encodeBatch(b))
	// Cut one byte before the CRC-valid end: the entire batch must vanish.
	rec, err := recoverState(full[:len(full)-1], map[string]string{}, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(rec.Applied) != 0 || len(rec.Mem) != 0 {
		t.Fatalf("partial batch applied: %+v", rec)
	}
	// With the last byte present, all keys appear together.
	rec, err = recoverState(full, map[string]string{}, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(rec.Mem) != 3 {
		t.Fatalf("atomic batch not fully applied: %+v", rec)
	}
}

// TestStaleEpochWriterRejected is the required fencing test.
func TestStaleEpochWriterRejected(t *testing.T) {
	dir := t.TempDir()
	a, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer a.Close()
	if err := a.Append([]Record{{Key: "x", Val: "1"}}); err != nil {
