// TestNewestDurableGenerationSelected proves recovery skips an SSTable whose
// fsync never completed (truncated/corrupt) even though the manifest points at
// it, and falls back to the newest checksum-clean generation.
func TestNewestDurableGenerationSelected(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	if err := s.Append([]Record{{Key: "k", Val: "durable"}}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.Flush(); err != nil { // generation 1
		t.Fatal(err)
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	// Simulate a generation 2 whose write/fsync never completed: truncated.
	if err := os.WriteFile(sstPath(dir, 2), []byte("half-written"), 0o644); err != nil {
		t.Fatal(err)
	}
	// Manifest dishonestly points at the torn generation 2.
	if err := writeManifestFsync(dir, Manifest{Epoch: 1, BaseGen: 2, BaseSeq: 1}); err != nil {
		t.Fatal(err)
	}

	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	v, ok := s2.Get("k")
	if !ok || v != "durable" {
		t.Fatalf("recovery picked torn generation: got %q ok=%v", v, ok)
	}
	// seq must not jump to the phantom generation.
	if s2.Seq() != 1 {
		t.Fatalf("seq=%d want 1", s2.Seq())
	}
	// New flush must not reuse generation 2 (it exists on disk).
	gen, err := s2.Flush()
	if err != nil {
		t.Fatal(err)
	}
	if gen <= 2 {
		t.Fatalf("reused generation %d", gen)
	}
}

// TestReopenRecoversAndTruncatesTornTail exercises the full Open path.
func TestReopenRecoversAndTruncatesTornTail(t *testing.T) {
	dir := t.TempDir()
	s, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	for i := 0; i < 5; i++ {
		if err := s.Append([]Record{{Key: "n", Val: fmt.Sprintf("%d", i)}}); err != nil {
			t.Fatal(err)
		}
	}
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

	// Append junk to the live WAL, then corrupt the last valid frame's CRC.
	walFile := filepath.Join(dir, "wal", "000001.wal")
	f, err := os.OpenFile(walFile, os.O_APPEND|os.O_WRONLY, 0o644)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := f.Write([]byte("torn-garbage")); err != nil {
		t.Fatal(err)
	}
	f.Close()

	s2, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	defer s2.Close()
	if got, _ := s2.Get("n"); got != "4" {
		t.Fatalf("recovered n=%q want 4", got)
	}
	if s2.Seq() != 5 {
		t.Fatalf("seq=%d want 5", s2.Seq())
