	if string(raw) == "torn-garbage" || len(raw) == 0 {
		t.Fatalf("torn tail not cleaned: %q", raw)
	}
	batches, _, _, torn := scanFrames(raw)
	if torn || len(batches) != 5 {
		t.Fatalf("expected 5 clean frames, got %d torn=%v", len(batches), torn)
	}
}

func equalKV(a, b map[string]string) bool {
	if len(a) != len(b) {
		return false
	}
	for k, v := range a {
		if b[k] != v {
			return false
		}
	}
	return true
}
